class stringx
{
public:
  stringx();
  stringx(const char *);
  stringx &operator=(const char *);
  stringx &operator+=(const char *);
  stringx &operator+=(const stringx &);
  const char *c_str() const;
  int length() const;
};

class pstring
{
public:
  const char *c_str() const;
};

class os_file
{
public:
  bool is_open() const;
  void write(void *, int);
};

class file_info_node
{
private:
  pstring name;
  char path[64];
  unsigned char ext[10];
  unsigned char *buffer;
  unsigned int buffer_size;
  unsigned short ref_count;
  unsigned char flag;

public:
  bool was_used() { return (flag & 8) != 0; }

  friend class file_manager;
};

template <class T>
class TreeNode
{
protected:
  TreeNode *l;
  TreeNode *r;
  TreeNode *p;
  T *d;
  char h;

public:
  TreeNode *left() { return l; }
  TreeNode *right() { return r; }
  T *data() { return d; }
};

class file_manager
{
private:
  char level_dir[64];

public:
  void write_level_cache_tree(os_file &fp, os_file &sfl,
                              TreeNode<file_info_node> *curr);
};

void file_manager::write_level_cache_tree(os_file &fp, os_file &sfl,
                                          TreeNode<file_info_node> *curr)
{
  if (curr == 0)
    return;
  file_info_node *me = curr->data();
  if (me->was_used())
  {
    stringx file_entry(me->path);
    file_entry += me->name.c_str();
    file_entry += (char *)me->ext;
    file_entry += "\r\n";
    fp.write((void *)file_entry.c_str(), file_entry.length());
    if (sfl.is_open())
    {
      stringx sfl_entry;
      if (me->path[0] != '\\' && me->path[0] != '\0')
      {
        sfl_entry = level_dir;
      }
      sfl_entry += file_entry;
      sfl.write((void *)sfl_entry.c_str(), sfl_entry.length());
    }
  }

  if (curr->left() != 0)
    write_level_cache_tree(fp, sfl, curr->left());
  if (curr->right() != 0)
    write_level_cache_tree(fp, sfl, curr->right());
}
